  getSensorMatrix: async () => {
    const beings = ["AETHER_PRIME", "CHRONOS_NEXUS", "PHANTOM_WITNESS", "ARCHITECT_MIRROR"];
    const types = ["Structural", "Temporal", "Field", "Presence"];
    const sensors = [];
    beings.forEach((beingId, bi) => {
      for (let i = 0; i < 100; i++) {
        const baseline = 50 + i % 40;
        const deviation = Math.sin(bi * 7 + i) * 8;
        const deviationAbs = Math.abs(deviation);
        const status = deviationAbs > 15 ? "CRITICAL" : deviationAbs > 8 ? "ALERT" : "NOMINAL";
        sensors.push({
          id: `${beingId.toLowerCase()}-s${String(i + 1).padStart(3, "0")}`,
          observationTarget: `Layer-${(bi + 1) * (i + 1)} ${types[i % 4]} field binding`,
          status,
          latinName: `Sensor ${beingId.charAt(0)}${i + 1}`,
          beingId,
          currentReading: baseline + deviation,
          sensorType: types[i % 4],
          name: `${beingId}_SENSOR_${String(i + 1).padStart(3, "0")}`,
          grade: "Field",
          anomalyThreshold: 15,
          baselineValue: baseline,
          family: "SENSOR",
          anomalyCount: BigInt(status === "CRITICAL" ? 3 : status === "ALERT" ? 1 : 0),
          lastReadingTs: BigInt(Date.now() - i * 873)
        });
      }
    });
    return sensors;
  },
